fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 0.5) {
        val whole = seconds.toLong()
        return if (seconds == whole.toDouble()) "${whole}s" else "%%.1f s".format(seconds).replace(" ", "")
    }
    val denominator = kotlin.math.round(1.0 / seconds).toLong()
    return "1/${denominator}s"
}

