"""Minimal move generator. Normal movement, captures, pawn double pushes.

Out of scope per requirements: castling, en passant, promotion, check/pin legality.
"""

FILES = "abcdefgh"


def _parse_fen(fen):
    parts = fen.split()
    if len(parts) < 2:
        raise ValueError("invalid FEN: expected at least placement and side-to-move")
    placement, side = parts[0], parts[1]
    if side not in ("w", "b"):
        raise ValueError("invalid FEN: side to move must be 'w' or 'b'")
    board = []
    for row_str in placement.split("/"):
        row = []
        for ch in row_str:
            if ch.isdigit():
                row.extend(["."] * int(ch))
            elif ch.isalpha():
                row.append(ch)
            else:
                raise ValueError(f"invalid FEN: bad character {ch!r}")
        if len(row) != 8:
            raise ValueError("invalid FEN: rank must contain 8 files")
        board.append(row)
    if len(board) != 8:
        raise ValueError("invalid FEN: placement must contain 8 ranks")
    return board, side


def _in_bounds(r, c):
    return 0 <= r < 8 and 0 <= c < 8


def _moves(board, side):
    """Yield (fr, fc, tr, tc) for every move of the side to move."""
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if piece == ".":
                continue
            color = "w" if piece.isupper() else "b"
            if color != side:
                continue
            letter = piece.lower()

            if letter == "p":
                dr = -1 if side == "w" else 1
                start_row = 6 if side == "w" else 1
                # single push
                nr = r + dr
                if _in_bounds(nr, c) and board[nr][c] == ".":
                    yield (r, c, nr, c)
                    # double push
                    dbl = r + 2 * dr
                    if r == start_row and board[nr][c] == "." and board[dbl][c] == ".":
                        yield (r, c, dbl, c)
                # captures
                for dc in (-1, 1):
                    nr, nc = r + dr, c + dc
                    if _in_bounds(nr, nc) and board[nr][nc] != "." and (
                        board[nr][nc].isupper() != (side == "w")
                    ):
                        yield (r, c, nr, nc)
            elif letter == "n":
                for dr, dc in ((-2, -1), (-2, 1), (-1, -2), (-1, 2),
                               (1, -2), (1, 2), (2, -1), (2, 1)):
                    nr, nc = r + dr, c + dc
                    if _in_bounds(nr, nc) and board[nr][nc] == "." or (
                        _in_bounds(nr, nc) and board[nr][nc] != "." and
                        (board[nr][nc].isupper() != (side == "w"))
                    ):
                        yield (r, c, nr, nc)
            elif letter == "k":
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if not _in_bounds(nr, nc):
                            continue
                        if board[nr][nc] == ".":
                            yield (r, c, nr, nc)
                        elif (board[nr][nc].isupper() != (side == "w")):
                            yield (r, c, nr, nc)
            elif letter in ("b", "r", "q"):
                dirs = []
                if letter in ("b", "q"):
                    dirs += [(-1, -1), (-1, 1), (1, -1), (1, 1)]
                if letter in ("r", "q"):
                    dirs += [(-1, 0), (1, 0), (0, -1), (0, 1)]
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    while _in_bounds(nr, nc) and board[nr][nc] != ".":
                        if board[nr][nc].isupper() != (side == "w"):
                            yield (r, c, nr, nc)
                            break
                        nr, nc = nr + dr, nc + dc
                    else:
                        pass
                    # note: loop exits when out of bounds or after capturing
                    # empty squares before the first piece are not yielded
                    # properly; handled below
                    # -- replaced by correct loop below --
                    # (kept for clarity; see _sliding_moves)
            elif letter == "q":
                pass


# The sliding-piece generator above is intentionally simple/incorrect for
# empty squares, so we rewrite it properly here.
def _sliding_moves(board, r, c, dirs, side, out):
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        while _in_bounds(nr, nc):
            target = board[nr][nc]
            if target == ".":
                out.append((r, c, nr, nc))
            else:
                if target.isupper() != (side == "w"):
                    out.append((r, c, nr, nc))
                break
            nr, nc = nr + dr, nc + dc


def _moves_full(board, side):
    out = []
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if piece == ".":
                continue
            color = "w" if piece.isupper() else "b"
            if color != side:
                continue
            letter = piece.lower()

            if letter == "p":
                dr = -1 if side == "w" else 1
                start_row = 6 if side == "w" else 1
                nr = r + dr
                if _in_bounds(nr, c) and board[nr][c] == ".":
                    out.append((r, c, nr, c))
                    dbl = r + 2 * dr
                    if r == start_row and board[nr][c] == "." and board[dbl][c] == ".":
                        out.append((r, c, dbl, c))
                for dc in (-1, 1):
                    nr, nc = r + dr, c + dc
                    if _in_bounds(nr, nc) and board[nr][nc] != ".":
                        t = board[nr][nc]
                        if t.isupper() != (side == "w"):
                            out.append((r, c, nr, nc))
            elif letter == "n":
                for dr, dc in ((-2, -1), (-2, 1), (-1, -2), (-1, 2),
                               (1, -2), (1, 2), (2, -1), (2, 1)):
                    nr, nc = r + dr, c + dc
                    if not _in_bounds(nr, nc):
                        continue
                    t = board[nr][nc]
                    if t == ".":
                        out.append((r, c, nr, nc))
                    elif t.isupper() != (side == "w"):
                        out.append((r, c, nr, nc))
            elif letter == "k":
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if not _in_bounds(nr, nc):
                            continue
                        t = board[nr][nc]
                        if t == ".":
                            out.append((r, c, nr, nc))
                        elif t.isupper() != (side == "w"):
                            out.append((r, c, nr, nc))
            elif letter in ("b", "r", "q"):
                dirs = []
                if letter in ("b", "q"):
                    dirs += [(-1, -1), (-1, 1), (1, -1), (1, 1)]
                if letter in ("r", "q"):
                    dirs += [(-1, 0), (1, 0), (0, -1), (0, 1)]
                _sliding_moves(board, r, c, dirs, side, out)
    return out


def _square(r, c):
    return FILES[c] + str(8 - r)


def legal_moves(fen):
    board, side = _parse_fen(fen)
    moves = []
    for fr, fc, tr, tc in _moves_full(board, side):
        moves.append(_square(fr, fc) + _square(tr, tc))
    return moves


def _apply(board, move, side):
    fr, fc, tr, tc = move
    nb = [row[:] for row in board]
    nb[tr][tc] = nb[fr][fc]
    nb[fr][fc] = "."
    return nb, ("b" if side == "w" else "w")


def _perft(board, side, depth):
    if depth == 0:
        return 1
    total = 0
    for move in _moves_full(board, side):
        nb, nside = _apply(board, move, side)
        total += _perft(nb, nside, depth - 1)
    return total


def perft(fen, depth):
    board, side = _parse_fen(fen)
    if depth < 0:
        raise ValueError("depth must be >= 0")
    return _perft(board, side, depth)

