"""

FILES = "abcdefgh"


def _parse_fen(fen):
    parts = fen.split()
    if len(parts) < 2:
        raise ValueError("invalid FEN: expected at least placement and side-to-move")
    placement, side = parts[0], parts[1]
    if side not in ("w", "b"):
        raise ValueError("invalid FEN: side to move must be 'w' or 'b'")
    rights = set()
    if len(parts) >= 3:
        rights = set(ch for ch in parts[2] if ch in "KQkq")
    board = []
    for row_str in placement.split("/"):
        row = []
        for ch in row_str:
            if ch.isdigit():
                row.extend(["."] * int(ch))
