            raise ValueError("invalid FEN: rank must contain 8 files")
        board.append(row)
    if len(board) != 8:
        raise ValueError("invalid FEN: placement must contain 8 ranks")
    return board, side, rights


def _in_bounds(r, c):
    return 0 <= r < 8 and 0 <= c < 8


def _is_enemy(target, side):
    return target != "." and (target.isupper() != (side == "w"))


def _is_attacked(board, r, c, by_side):
    for fr, fc, tr, tc, _ in _moves(board, by_side, set(), allow_castle=False):
        if tr == r and tc == c:
            return True
    return False


