    row = 7 if side == "w" else 0
    king_ch = "K" if side == "w" else "k"
    rook_ch = "R" if side == "w" else "r"
    enemy_ch = "b" if side == "w" else "w"
    moves = []
    if board[row][4] != king_ch:
        return moves
    kingside_right = "K" if side == "w" else "k"
    queenside_right = "Q" if side == "w" else "q"
    if kingside_right in rights and board[row][7] == rook_ch and \
            board[row][5] == "." and board[row][6] == "." and \
            not _is_attacked(board, row, 4, enemy_ch) and \
            not _is_attacked(board, row, 5, enemy_ch) and \
            not _is_attacked(board, row, 6, enemy_ch):
        moves.append((row, 4, row, 6, (row, 7, row, 5)))
    if queenside_right in rights and board[row][0] == rook_ch and \
            board[row][3] == "." and board[row][2] == "." and \
            not _is_attacked(board, row, 4, enemy_ch) and \
            not _is_attacked(board, row, 3, enemy_ch) and \
            not _is_attacked(board, row, 2, enemy_ch):
        moves.append((row, 4, row, 2, (row, 0, row, 3)))
