            elif letter == "k":
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if not _in_bounds(nr, nc):
                            continue
                        t = board[nr][nc]
                        if t == "." or _is_enemy(t, side):
                            out.append((r, c, nr, nc, None, None, None))
            elif letter in ("b", "r", "q"):
                dirs = []
                if letter in ("b", "q"):
                    dirs += [(-1, -1), (-1, 1), (1, -1), (1, 1)]
                if letter in ("r", "q"):
                    dirs += [(-1, 0), (1, 0), (0, -1), (0, 1)]
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    while _in_bounds(nr, nc):
                        t = board[nr][nc]
                        if t == ".":
                            out.append((r, c, nr, nc, None, None, None))
                        else:
                            if _is_enemy(t, side):
                                out.append((r, c, nr, nc, None, None, None))
                            break
                        nr, nc = nr + dr, nc + dc
    if allow_castle and rights:
        out.extend(_castle_moves(board, side, rights))
    return out


def _square(r, c):
    return FILES[c] + str(8 - r)


def legal_moves(fen):
    board, side, rights, ep = _parse_fen(fen)
    return [_square(fr, fc) + _square(tr, tc) + (promo if promo else "") for fr, fc, tr, tc, _, _, promo in _moves(board, side, rights, ep)]


def _apply(board, move, side, rights):
    fr, fc, tr, tc, rook, ep_cap, promo = move
    nb = [row[:] for row in board]
    piece = nb[fr][fc]
    captured = nb[tr][tc]
    if promo is not None:
        nb[tr][tc] = promo.upper() if side == "w" else promo
    else:
        nb[tr][tc] = piece
    nb[fr][fc] = "."
    if ep_cap is not None:
        er, ec = ep_cap
        nb[er][ec] = "."
    if rook is not None:
        rf, rc, rt, rq = rook
        nb[rt][rq] = nb[rf][rc]
        nb[rf][rc] = "."
    new = set(rights)
    if piece == "K":
        new -= {"K", "Q"}
    elif piece == "k":
        new -= {"k", "q"}
    elif piece == "R":
        if (fr, fc) == (7, 0):
            new -= {"Q"}
        elif (fr, fc) == (7, 7):
            new -= {"K"}
    elif piece == "r":
        if (fr, fc) == (0, 0):
            new -= {"q"}
        elif (fr, fc) == (0, 7):
            new -= {"k"}
    if captured == "R":
        if (tr, tc) == (7, 0):
            new -= {"Q"}
        elif (tr, tc) == (7, 7):
            new -= {"K"}
    elif captured == "r":
        if (tr, tc) == (0, 0):
            new -= {"q"}
        elif (tr, tc) == (0, 7):
            new -= {"k"}
    new_ep = None
    if rook is None and piece == "p" and abs(tr - fr) == 2:
        new_ep = (fr + (tr - fr) // 2, fc)
    return nb, ("b" if side == "w" else "w"), new, new_ep


def _perft(board, side, rights, ep, depth):
    if depth == 0:
        return 1
    total = 0
    for move in _moves(board, side, rights, ep):
        nb, nside, nrights, nep = _apply(board, move, side, rights)
        total += _perft(nb, nside, nrights, nep, depth - 1)
    return total


def perft(fen, depth):
    board, side, rights, ep = _parse_fen(fen)
    if depth < 0:
        raise ValueError("depth must be >= 0")
    return _perft(board, side, rights, ep, depth)

